using System;
using System.Collections.Generic;
using System.Data;
using System.Data.Odbc;
using System.Globalization;
using System.Text;

internal sealed partial class HPAddressClient
{
 Dictionary<string,object> Definition(string key){return (Dictionary<string,object>)json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(Convert.FromBase64String(FullSpecBase64)))[key];}
 Dictionary<string,object> EmptyRow(string key){var row=new Dictionary<string,object>();foreach(Dictionary<string,object> f in (System.Collections.ArrayList)Definition(key)["fields"])row[Convert.ToString(f["name"])]=Convert.ToInt32(f["typ"])==0||Convert.ToInt32(f["typ"])==13?"":"0";return row;}
 static int Number(object n){return Convert.ToInt32(n,CultureInfo.InvariantCulture);}
 static void Parameter(OdbcCommand cmd,Dictionary<string,object> field,object value){int type=Number(field["typ"]);string s=Convert.ToString(value,CultureInfo.InvariantCulture);if(type==0||type==13)cmd.Parameters.Add("v",OdbcType.VarChar,Number(field["max"])).Value=s;else if(type==7)cmd.Parameters.Add("v",OdbcType.Bit).Value=s=="1";else if(type==2)cmd.Parameters.Add("v",OdbcType.Double).Value=Convert.ToDouble(s,CultureInfo.InvariantCulture);else if(type==1)cmd.Parameters.Add("v",OdbcType.Int).Value=Number(s);else throw new InvalidOperationException("Nicht freigegebener HP-Feldtyp.");}
 void Insert(OdbcConnection c,OdbcTransaction tx,string key,Dictionary<string,object> row){var p=Definition(key);var columns=new List<string>();var marks=new List<string>();using(var cmd=new OdbcCommand()){cmd.Connection=c;cmd.Transaction=tx;cmd.CommandTimeout=15;foreach(Dictionary<string,object> f in (System.Collections.ArrayList)p["fields"]){string name=Convert.ToString(f["name"]);columns.Add(Quoted(name));marks.Add("?");Parameter(cmd,f,row[name]);}cmd.CommandText="INSERT INTO "+Quoted(Convert.ToString(p["table"]))+" ("+String.Join(",",columns)+") VALUES ("+String.Join(",",marks)+")";if(cmd.ExecuteNonQuery()!=1)throw new InvalidOperationException("HP-Neuanlage nicht eindeutig.");}}
 List<Dictionary<string,object>> ReadRows(OdbcConnection c,OdbcTransaction tx,string key,int n){var p=Definition(key);var cols=new List<string>();foreach(Dictionary<string,object> f in (System.Collections.ArrayList)p["fields"])cols.Add(Quoted(Convert.ToString(f["name"])));string sql="SELECT "+String.Join(",",cols)+" FROM "+Quoted(Convert.ToString(p["table"]))+" WHERE "+Quoted(Convert.ToString(p["adr"]))+"=?";if(key=="protokoll")sql+=" AND MODUL='ADR'";var rows=new List<Dictionary<string,object>>();using(var cmd=new OdbcCommand(sql,c,tx)){cmd.CommandTimeout=15;cmd.Parameters.Add("n",OdbcType.Int).Value=n;using(var r=cmd.ExecuteReader())while(r.Read()){if(rows.Count>10)throw new InvalidOperationException("Unerwartete HP-Folgeeinträge.");var row=new Dictionary<string,object>();foreach(Dictionary<string,object> f in (System.Collections.ArrayList)p["fields"]){string name=Convert.ToString(f["name"]);object v=r[name];row[name]=v==DBNull.Value?null:v is bool?((bool)v?"1":"0"):Convert.ToString(v,CultureInfo.InvariantCulture).TrimEnd(' ');}rows.Add(row);}}return rows;}
 internal static bool EqualRows(List<Dictionary<string,object>> actual,List<Dictionary<string,object>> expected){if(actual.Count!=expected.Count)return false;var remaining=new List<Dictionary<string,object>>(actual);foreach(var wanted in expected){int index=remaining.FindIndex(delegate(Dictionary<string,object> row){foreach(var f in wanted)if(!row.ContainsKey(f.Key)||!String.Equals(Convert.ToString(f.Value,CultureInfo.InvariantCulture),Convert.ToString(row[f.Key],CultureInfo.InvariantCulture),StringComparison.Ordinal))return false;return true;});if(index<0)return false;remaining.RemoveAt(index);}return true;}
 internal Dictionary<string,List<Dictionary<string,object>>> Expected(Dictionary<string,object> data,Dictionary<string,object> reservation){int n=Number(reservation["nummer"]);var record=(Dictionary<string,object>)data["record"];if(!Valid(record))throw new InvalidOperationException("Ungültige HP-Neuanlage.");string sb=Convert.ToString(data["sb"]);if(!System.Text.RegularExpressions.Regex.IsMatch(sb,@"\A[A-Z]{1,3}\z"))throw new InvalidOperationException();
  var result=new Dictionary<string,List<Dictionary<string,object>>>();foreach(string key in new[]{"stamm","anlage","telefon","email","protokoll"})result[key]=new List<Dictionary<string,object>>();
  var main=EmptyRow("stamm");main["AdrNr"]=n.ToString(CultureInfo.InvariantCulture);for(int i=0;i<Keys.Length;i++)main[Columns[i]]=record[Keys[i]];main["SBegrAdr"]=Convert.ToString(record["name1"]).ToUpperInvariant();result["stamm"].Add(main);
  var created=EmptyRow("anlage");created["AdrNr"]=n.ToString(CultureInfo.InvariantCulture);created["anDatum"]=Convert.ToString(reservation["datum"],CultureInfo.InvariantCulture);created["anVonSB"]=sb;result["anlage"].Add(created);
  int index=0;foreach(string field in new[]{"telefon","mobil"}){string value=Convert.ToString(data[field]);if(value.Length==0)continue;if(value.Length>25)throw new InvalidOperationException();index++;var r=EmptyRow("telefon");r["AdrNr"]=n.ToString(CultureInfo.InvariantCulture);r["Laufende_Nummer"]=index.ToString();r["LfdNrIDXTel"]=index.ToString();r["TelNr"]=value;r["TelTxt"]=field=="mobil"?"Mobil":"Telefon";result["telefon"].Add(r);}
  string mail=Convert.ToString(data["email"]);if(mail.Length>0){if(mail.Length>60)throw new InvalidOperationException();var r=EmptyRow("email");r["Adress_Nr"]=n.ToString(CultureInfo.InvariantCulture);r["lfd__Nr"]=r["LfdIDXMail"]="1";r["eMail_Adresse___Webs"]=mail;r["eMail"]=r["Standard"]="1";r["Suchbegriff"]=mail.ToUpperInvariant().Substring(0,Math.Min(mail.Length,30));result["email"].Add(r);}
  long sequence=Convert.ToInt64(reservation["protokoll"]);foreach(string key in new[]{"stamm","telefon","email"}){int child=0;foreach(var ignored in result[key]){child++;var r=EmptyRow("protokoll");r["Datum"]=reservation["datum"].ToString();r["Uhrzeit"]=reservation["uhrzeit"].ToString();r["SB"]=sb;r["Typ"]="C";r["MODUL"]="ADR";r["MODUL_ID"]=key=="stamm"?"NEUANL":key=="telefon"?"TELEFO":"EMAIL";r["IDX"]=n.ToString(CultureInfo.InvariantCulture);r["IDX1n"]=key=="stamm"?"0":child.ToString();r["lfdNr"]=(sequence++).ToString(CultureInfo.InvariantCulture);result["protokoll"].Add(r);}}
  return result;
 }
 bool Proof(OdbcConnection c,OdbcTransaction tx,Dictionary<string,List<Dictionary<string,object>>> expected,int n){foreach(var p in expected)if(!EqualRows(ReadRows(c,tx,p.Key,n),p.Value))return false;return true;}
 bool Duplicate(OdbcConnection c,OdbcTransaction tx,Dictionary<string,object> data){var record=(Dictionary<string,object>)data["record"];var known=new HashSet<int>();foreach(object raw in (System.Collections.ArrayList)data["bekannte_hp"])known.Add(Number(raw));using(var cmd=new OdbcCommand("SELECT AdrNr FROM AD_Adr WHERE UPPER(Name1)=UPPER(?) AND (UPPER(Vorname)=UPPER(?) OR (Vorname IS NULL AND ?=''))",c,tx)){cmd.CommandTimeout=15;cmd.Parameters.Add("name",OdbcType.VarChar,30).Value=record["name1"];cmd.Parameters.Add("vorname",OdbcType.VarChar,30).Value=record["vorname"];cmd.Parameters.Add("leer",OdbcType.VarChar,30).Value=record["vorname"];using(var r=cmd.ExecuteReader())while(r.Read())if(!known.Contains(Number(r[0])))return true;}
  string mail=Convert.ToString(data["email"]);if(mail.Length>0)using(var cmd=new OdbcCommand("SELECT Adress_Nr FROM AD_eMail WHERE UPPER(eMail_Adresse___Webs)=UPPER(?)",c,tx)){cmd.CommandTimeout=15;cmd.Parameters.Add("mail",OdbcType.VarChar,60).Value=mail;using(var r=cmd.ExecuteReader())while(r.Read())if(!known.Contains(Number(r[0])))return true;}return false;
 }
 object Scalar(OdbcConnection c,OdbcTransaction tx,string sql){using(var cmd=new OdbcCommand(sql,c,tx)){cmd.CommandTimeout=15;return cmd.ExecuteScalar();}}
 Dictionary<string,object> CreateAddress(Dictionary<string,object> job){bool commit=false;string phase="vorpruefung";var data=(Dictionary<string,object>)job["daten"];OdbcTransaction tx=null;using(var c=Open())try{
   tx=c.BeginTransaction(IsolationLevel.Serializable);if(Duplicate(c,tx,data)){tx.Rollback();return Result("dublette",null);}
   phase="nummer";int old=Number(Scalar(c,tx,"SELECT SY_AdrNr FROM SY_LfdNum WHERE Init='@'"));if(old<1||old>=Int32.MaxValue)throw new InvalidOperationException();int n=old+1;
   // Reserve through HP's verified highest-used counter, never MAX(AdrNr)+1.
   using(var cmd=new OdbcCommand("UPDATE SY_LfdNum SET SY_AdrNr=? WHERE Init='@' AND SY_AdrNr=?",c,tx)){cmd.CommandTimeout=15;cmd.Parameters.Add("next",OdbcType.Int).Value=n;cmd.Parameters.Add("old",OdbcType.Int).Value=old;if(cmd.ExecuteNonQuery()!=1)throw new InvalidOperationException();}
   foreach(string key in json.Deserialize<Dictionary<string,object>>(Encoding.UTF8.GetString(Convert.FromBase64String(FullSpecBase64))).Keys)if(ReadRows(c,tx,key,n).Count!=0)throw new InvalidOperationException("Reservierte HP-Nummer bereits belegt.");
   double maximum=Convert.ToDouble(Scalar(c,tx,"SELECT MAX(lfdNr) FROM SY_DSGVO_Aenderung"),CultureInfo.InvariantCulture);if(maximum<1||maximum!=Math.Truncate(maximum)||maximum>9007199254740980d)throw new InvalidOperationException();
   var now=DateTime.Now;var reservation=new Dictionary<string,object>{{"nummer",n},{"datum",(now.Date-DateTime.MinValue.Date).Days+1},{"uhrzeit",(int)now.TimeOfDay.TotalSeconds},{"protokoll",(long)maximum+1}};
   var expected=Expected(data,reservation);
   // Persist the binding before any insert; interruption can only cause read-back, never a second insert.
   phase="reservierung";var bound=Post("neuanlagen/reservieren",new{datenbank=database,id=job["id"],reservierung=reservation});if(!bound.ContainsKey("ok")||!Convert.ToBoolean(bound["ok"]))throw new InvalidOperationException("HP-Nummer nicht dauerhaft bestätigt.");
   foreach(var p in expected){phase=p.Key;foreach(var row in p.Value)Insert(c,tx,p.Key,row);}
   phase="rueckpruefung";
   if(!Proof(c,tx,expected,n))throw new InvalidOperationException("HP-Rückprüfung vor Commit fehlgeschlagen.");phase="commit";commit=true;tx.Commit();tx.Dispose();tx=null;
   phase="nachpruefung";if(!Proof(c,null,expected,n)){var mismatch=Result("unklar",null);mismatch["diagnose"]=phase;return mismatch;}var record=new Dictionary<string,object>((Dictionary<string,object>)data["record"]);record["nummer"]=n;var done=Result("erfolg",record);done["vollstaendig_geprueft"]=true;return done;
  }catch(Exception e){bool rolled=false;if(tx!=null&&!commit)try{tx.Rollback();rolled=true;}catch{}var result=Result(rolled?"fehler":"unklar",null);var odbc=e as OdbcException;string state=odbc!=null&&odbc.Errors.Count>0?odbc.Errors[0].SQLState:null;result["diagnose"]=phase+(state!=null&&System.Text.RegularExpressions.Regex.IsMatch(state,@"\A[A-Z0-9]{4,5}\z")?"/"+state:"");return result;}finally{if(tx!=null)tx.Dispose();}
 }
 Dictionary<string,object> CheckCreated(Dictionary<string,object> job){var reservation=(Dictionary<string,object>)job["reservierung"];using(var c=Open()){if(!Proof(c,null,Expected((Dictionary<string,object>)job["daten"],reservation),Number(reservation["nummer"])))return Result("unklar",null);var record=new Dictionary<string,object>((Dictionary<string,object>)((Dictionary<string,object>)job["daten"])["record"]);record["nummer"]=reservation["nummer"];var done=Result("erfolg",record);done["vollstaendig_geprueft"]=true;return done;}}
 void NewAddressStep(Queue<Dictionary<string,object>> pending,Action<string> log){while(pending.Count>0){Post("neuanlagen/ergebnis",pending.Peek());pending.Dequeue();}var response=Post("neuanlagen/abholen",new{datenbank=database});object raw;bool readOnly=response.TryGetValue("pruefen",out raw);if(!readOnly&&!response.TryGetValue("anlegen",out raw))return;var job=(Dictionary<string,object>)raw;Guid parsed;if(!Guid.TryParse(Convert.ToString(job["id"]),out parsed))throw new InvalidOperationException();Dictionary<string,object> result;try{result=readOnly?CheckCreated(job):CreateAddress(job);}catch{result=Result("unklar",null);}result["datenbank"]=database;result["id"]=job["id"];pending.Enqueue(result);log("HP-Neuanlage: "+result["status"]+(result.ContainsKey("diagnose")?" ("+result["diagnose"]+")":"")+". Kein automatischer zweiter Anlageversuch.");while(pending.Count>0){Post("neuanlagen/ergebnis",pending.Peek());pending.Dequeue();}}
}
